import itertools, random

def all_sigmas(m):
    return list(itertools.product([False, True], repeat=m))

m = 4
sigmas = all_sigmas(m)
for i in range(m):
    s = sum(1.0 if sig[i] else -1.0 for sig in sigmas)
    assert abs(s) < 1e-12
print('Theorem 3.1 (cancellation) verified for all coordinates.')

random.seed(0)
f = [random.uniform(-3, 3) for _ in range(m)]
def rad_sum(f, sig):
    return sum((1.0 if s else -1.0)*fi for s, fi in zip(sig, f))
tot = sum(rad_sum(f, sig) for sig in sigmas)
assert abs(tot) < 1e-9
print('Theorem 4.1 (zero mean) verified.')

import itertools, random

def all_sigmas(m):
    return list(itertools.product([False, True], repeat=m))

def rad_sum(f, sig):
    return sum((1.0 if s else -1.0)*fi for s, fi in zip(sig, f))

def emp_rad(F):
    m = len(F[0]); S = all_sigmas(m)
    return (1.0/m)*(1.0/2**m)*sum(max(rad_sum(f, s) for f in F) for s in S)

random.seed(1); m = 4
for _ in range(50):
    base = [[random.uniform(-2,2) for _ in range(m)] for _ in range(2)]
    extra = [random.uniform(-2,2) for _ in range(m)]
    assert emp_rad(base) <= emp_rad(base + [extra]) + 1e-9
print('Theorem 4.4 (monotonicity) verified over 50 trials.')

